intfalsefileperms stringfilename
Возвращает информацию о правах доступа на файл.

  &reftitle.examples;



    Отображение прав доступа в виде восьмеричного числа


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    Отображение полных прав доступа


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0xC000: $info = 's'; break; // сокет
    case 0xA000: $info = 'l'; break; // символическая ссылка
    case 0x8000: $info = 'r'; break; // обычный
    case 0x6000: $info = 'b'; break; // файл блочного устройства
    case 0x4000: $info = 'd'; break; // каталог
    case 0x2000: $info = 'c'; break; // файл символьного устройства
    case 0x1000: $info = 'p'; break; // FIFO канал

    // неизвестный
    default: $info = 'u';
}

// Владелец
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Группа
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Мир
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


-rw-r--r--
